{
  "name": "TC200温度控制器",
  "name_en": "TC200 Temperature Controller",
  "manufacturer": "Thorlabs",
  "description": "Thorlabs TC200 是一款实验室温度控制器，用于驱动加热元件输出电压、读取热敏电阻温度，并通过 PID 调节将温度稳定在设定值。适用于样品加热、光学或机电实验中的温度稳定与热管理。",
  "description_en": "The Thorlabs TC200 is a laboratory temperature controller that drives a heating element, reads temperature from a thermistor, and uses PID regulation to hold the temperature at a setpoint. It is used for sample heating, thermal stabilization, and temperature management in optical or electromechanical experiments.",
  "tag_hints": [
    "temperature control",
    "PID heater control",
    "thermistor sensing",
    "laboratory heating",
    "temperature stabilization",
    "Thorlabs TC200"
  ],
  "actions": [
    {
      "action_name": "auto-beta",
      "description": "获取/设置/定义热敏电阻 Beta 参数",
      "description_en": "get/set/define the thermistor beta parameter"
    },
    {
      "action_name": "auto-d",
      "description": "获取/设置/定义 D 增益",
      "description_en": "get/set/define the D gain"
    },
    {
      "action_name": "auto-degrees",
      "description": "获取/设置/定义温度单位",
      "description_en": "get/set/define the temperature units"
    },
    {
      "action_name": "auto-enable",
      "description": "获取/设置/定义加热输出使能状态",
      "description_en": "get/set/define the heater output enable state"
    },
    {
      "action_name": "auto-i",
      "description": "获取/设置/定义 I 增益",
      "description_en": "get/set/define the I gain"
    },
    {
      "action_name": "auto-max_power",
      "description": "获取/设置/定义最大输出功率",
      "description_en": "get/set/define the maximum output power"
    },
    {
      "action_name": "auto-max_temperature",
      "description": "获取/设置/定义最高允许温度",
      "description_en": "get/set/define the maximum allowed temperature"
    },
    {
      "action_name": "auto-mode",
      "description": "获取/设置/定义输出模式",
      "description_en": "get/set/define the output mode"
    },
    {
      "action_name": "auto-name",
      "description": "读取设备名称和版本信息",
      "description_en": "read the device name and version information"
    },
    {
      "action_name": "auto-p",
      "description": "获取/设置/定义 P 增益",
      "description_en": "get/set/define the P gain"
    },
    {
      "action_name": "auto-pid",
      "description": "获取/设置/定义 PID 参数",
      "description_en": "get/set/define the PID parameters"
    },
    {
      "action_name": "auto-sensor",
      "description": "获取/设置/定义温度传感器配置",
      "description_en": "get/set/define the temperature sensor configuration"
    },
    {
      "action_name": "auto-temperature_set",
      "description": "获取/设置/定义目标温度",
      "description_en": "get/set/define the target temperature"
    },
    {
      "action_name": "auto-status",
      "description": "获取状态代码",
      "description_en": "get the status code"
    }
  ]
}

